import { z } from 'zod'

// ---------------------------------------------------------------------------
// Repair Status — lifecycle states
// ---------------------------------------------------------------------------

export const repairStatusSchema = z.enum([
  'intake', 'in_progress', 'on_hold', 'verified', 'ready', 'completed', 'cancelled'
])

/** A valid repair status */
export type RepairStatus = z.infer<typeof repairStatusSchema>

// ---------------------------------------------------------------------------
// Hold Reason — why a repair is paused
// ---------------------------------------------------------------------------

export const holdReasonSchema = z.enum([
  'waiting_parts', 'awaiting_customer_approval', 'other'
])

/** A valid hold reason */
export type HoldReason = z.infer<typeof holdReasonSchema>

// ---------------------------------------------------------------------------
// Repair Line Item Type
// ---------------------------------------------------------------------------

export const repairLineItemTypeSchema = z.enum(['part', 'labor'])

/** A valid line item type for repairs */
export type RepairLineItemType = z.infer<typeof repairLineItemTypeSchema>

// ---------------------------------------------------------------------------
// Customer Mode — existing or new customer during intake
// ---------------------------------------------------------------------------

export const customerModeSchema = z.enum(['existing', 'new'])

/** Whether the intake form is selecting an existing or creating a new customer */
export type CustomerMode = z.infer<typeof customerModeSchema>

// ---------------------------------------------------------------------------
// Bicycle Mode — select existing or create new during intake
// ---------------------------------------------------------------------------

export const bicycleModeSchema = z.enum(['select_existing', 'create_new'])

/** Whether the intake form is selecting an existing or creating a new bicycle */
export type BicycleMode = z.infer<typeof bicycleModeSchema>

// ---------------------------------------------------------------------------
// Inline Customer Creation — minimal fields for walk-in customers
// ---------------------------------------------------------------------------

/** New customer data captured during repair intake (minimal set) */
export const createIntakeCustomerSchema = z.object({
  firstName: z.string().min(1, 'firstName is required').max(100).optional(),
  lastName: z.string().min(1, 'lastName is required').max(100).optional(),
  companyName: z.string().min(1, 'companyName is required').max(200).optional(),
  phone: z.string().min(1, 'phone is required').max(50),
  email: z.string().min(1, 'email is required').max(50).optional().or(z.literal('')),
})

/** Input for creating a new customer during repair intake */
export type CreateIntakeCustomerInput = z.infer<typeof createIntakeCustomerSchema>

// ---------------------------------------------------------------------------
// Inline Bicycle Creation — brand, model, color only
// ---------------------------------------------------------------------------

/** New bicycle data captured during repair intake (minimal set) */
export const createIntakeBicycleSchema = z.object({
  brand: z.string().min(1, 'brand is required').max(100),
  model: z.string().min(1, 'model is required').max(200),
  color: z.string().min(1, 'color is required').max(50),
})

/** Input for creating a new bicycle during repair intake */
export type CreateIntakeBicycleInput = z.infer<typeof createIntakeBicycleSchema>

// ---------------------------------------------------------------------------
// Repair Intake — combined customer + bicycle + notes submission
// ---------------------------------------------------------------------------

/** Customer selection data (when selecting existing) */
const existingCustomerData = z.object({
  id: z.string().uuid('id must be a valid UUID'),
})

/** New customer creation data (when creating inline) */
const newCustomerData = createIntakeCustomerSchema

/** Bicycle selection data (when selecting existing) */
const existingBicycleData = z.object({
  id: z.string().uuid('id must be a valid UUID'),
})

/** New bicycle creation data (when creating inline) */
const newBicycleData = createIntakeBicycleSchema

/** Complete repair intake input — validates customer/bicycle mode + required fields */
export const repairIntakeSchema = z.discriminatedUnion('customerMode', [
  // Existing customer path
  z.object({
    customerMode: z.literal('existing'),
    existingCustomerId: z.string().uuid('existingCustomerId must be a valid UUID'),
    bicycleMode: bicycleModeSchema,
    existingBicycleId: z.string().uuid('existingBicycleId required when selecting existing bicycle').optional(),
    newBicycle: createIntakeBicycleSchema.optional(),
    customerNotes: z.string().min(1, 'customerNotes is required').max(2000, 'customerNotes must be 2000 characters or less'),
    plannedDate: z.number().nullable().optional(),
    pickupDate: z.number().nullable().optional(),
  }),
  // New customer path (inline creation)
  z.object({
    customerMode: z.literal('new'),
    newCustomer: createIntakeCustomerSchema,
    bicycleMode: bicycleModeSchema,
    existingBicycleId: z.string().uuid('existingBicycleId required when selecting existing bicycle').optional(),
    newBicycle: createIntakeBicycleSchema.optional(),
    customerNotes: z.string().min(1, 'customerNotes is required').max(2000, 'customerNotes must be 2000 characters or less'),
    plannedDate: z.number().nullable().optional(),
    pickupDate: z.number().nullable().optional(),
  }),
]).refine(
  (data) => {
    // Bicycle mode validation: select_existing requires existingBicycleId, create_new requires newBicycle
    if (data.bicycleMode === 'select_existing' && !data.existingBicycleId) {
      return false
    }
    if (data.bicycleMode === 'create_new' && !data.newBicycle) {
      return false
    }
    return true
  },
  { message: 'When bicycleMode is select_existing, existingBicycleId is required; when create_new, newBicycle is required' }
)

/** Input for creating a repair via the intake flow */
export type RepairIntakeInput = z.infer<typeof repairIntakeSchema>

// ---------------------------------------------------------------------------
// Status Transition — changing repair status
// ---------------------------------------------------------------------------

/** Input for transitioning a repair to a new status */
export const transitionRepairStatusSchema = z.object({
  targetStatus: repairStatusSchema,
  holdReason: holdReasonSchema.optional(),
  holdReasonNote: z.string().max(500).optional(),
})

/** Input for transitioning a repair's status */
export type TransitionRepairStatusInput = z.infer<typeof transitionRepairStatusSchema>

// ---------------------------------------------------------------------------
// Repair Update — partial update of notes, dates, assignment
// ---------------------------------------------------------------------------

/** Partial fields that can be updated on an existing repair */
export const updateRepairSchema = z.object({
  customerNotes: z.string().max(2000).optional(),
  internalNotes: z.string().max(5000).optional(),
  holdReason: holdReasonSchema.nullable().optional(),
  holdReasonNote: z.string().max(500).nullable().optional(),
  plannedDate: z.number().nullable().optional(),
  pickupDate: z.number().nullable().optional(),
  assignedTo: z.string().uuid('assignedTo must be a valid UUID').or(z.null()).optional(),
}).refine(
  (data) => {
    // holdReasonNote is required when holdReason is set to non-null
    if (data.holdReason !== undefined && data.holdReason !== null && !data.holdReasonNote) {
      return false
    }
    return true
  },
  { message: 'holdReasonNote is required when holdReason is set' }
)

/** Input for updating an existing repair */
export type UpdateRepairInput = z.infer<typeof updateRepairSchema>

// ---------------------------------------------------------------------------
// Repair Line Item — creating/updating line items on a repair
// ---------------------------------------------------------------------------

/** Base fields common to all line item creation inputs */
const baseLineItemFields = {
  description: z.string().min(1, 'description is required').max(500),
  quantity: z.number().int().positive('quantity must be positive').default(1),
  unitPriceNet: z.number().int().nonnegative('unitPriceNet must be non-negative'),
  vatRateId: z.string().min(1, 'vatRateId is required').or(z.null()),
  discountPercent: z.number().int().min(0).max(10000).nullable().optional(),
}

/** Input for creating a part-based line item on a repair */
export const createPartLineItemSchema = z.object({
  ...baseLineItemFields,
  lineType: z.literal('part'),
  partId: z.string().min(1, 'partId is required'),
})

/** Input for creating a labor-based line item on a repair */
export const createLaborLineItemSchema = z.object({
  ...baseLineItemFields,
  lineType: z.literal('labor'),
  laborServiceId: z.string().min(1, 'laborServiceId is required'),
  minutesWorked: z.number().int().positive().nullable().optional(),
  hourlyRateSnapshot: z.number().int().nonnegative().nullable().optional(),
})

/** Discriminated union for creating any line item type */
export const createRepairLineItemSchema = z.discriminatedUnion('lineType', [
  createPartLineItemSchema,
  createLaborLineItemSchema,
])

/** Input for updating an existing repair line item */
export const updateRepairLineItemSchema = z.object({
  quantity: z.number().int().positive().optional(),
  unitPriceNet: z.number().int().nonnegative().optional(),
  discountPercent: z.number().int().min(0).max(10000).nullable().optional(),
  minutesWorked: z.number().int().positive().nullable().optional(),
  hourlyRateSnapshot: z.number().int().nonnegative().nullable().optional(),
})

/** Input for assigning or changing the assigned worker on a repair */
export const assignWorkerSchema = z.object({
  assignedTo: z.string().uuid('assignedTo must be a valid UUID').or(z.null()),
})

// ---------------------------------------------------------------------------
// Type exports
// ---------------------------------------------------------------------------

/** Input type for creating a part line item */
export type CreatePartLineItemInput = z.infer<typeof createPartLineItemSchema>

/** Input type for creating a labor line item */
export type CreateLaborLineItemInput = z.infer<typeof createLaborLineItemSchema>

/** Input type for creating any repair line item */
export type CreateRepairLineItemInput = z.infer<typeof createRepairLineItemSchema>

/** Input type for updating a repair line item */
export type UpdateRepairLineItemInput = z.infer<typeof updateRepairLineItemSchema>

/** Input type for assigning a worker to a repair */
export type AssignWorkerInput = z.infer<typeof assignWorkerSchema>

// ---------------------------------------------------------------------------
// Payment Completion — atomic transaction at repair completion
// ---------------------------------------------------------------------------

/** A single payment method entry for split payments */
const repairPaymentMethodSchema = z.object({
  method: z.enum(['cash', 'card']),
  amount: z.number().int().positive('amount must be positive'),
})

/** Input schema for completing a repair with payment data (single or split) */
export const completeRepairPaymentSchema = z.object({
  payments: z.array(repairPaymentMethodSchema)
    .min(1, 'At least one payment method is required')
    .refine(
      (data) => {
        // Validate that total matches the repair's line item totals
        return true // validated server-side with actual repair totals
      },
      { message: 'Payment amounts must match repair total' }
    ),
}).refine(
  (data) => data.payments.length >= 1,
  { message: 'At least one payment method is required', path: ['payments'] }
)

/** Input type for completing a repair with payment */
export type CompleteRepairPaymentInput = z.infer<typeof completeRepairPaymentSchema>

import { z } from 'zod'

// ---------------------------------------------------------------------------
// Quote Status — lifecycle states
// ---------------------------------------------------------------------------

export const quoteStatusSchema = z.enum([
  'draft', 'sent', 'converted', 'rejected'
])

/** A valid quote status */
export type QuoteStatus = z.infer<typeof quoteStatusSchema>

// ---------------------------------------------------------------------------
// Line Item Type
// ---------------------------------------------------------------------------

export const quoteLineItemTypeSchema = z.enum(['part', 'labor', 'bicycle'])

/** A valid line item type for quotes */
export type QuoteLineItemType = z.infer<typeof quoteLineItemTypeSchema>

// ---------------------------------------------------------------------------
// Create Quote Input
// ---------------------------------------------------------------------------

export const createQuoteSchema = z.object({
  customerId: z.string().uuid('customerId must be a valid UUID').optional().nullable(),
  notes: z.string().max(2000).optional().nullable(),
})

/** Input for creating a new quote */
export type CreateQuoteInput = z.infer<typeof createQuoteSchema>

// ---------------------------------------------------------------------------
// Update Quote Input — draft fields only
// ---------------------------------------------------------------------------

export const updateQuoteSchema = z.object({
  customerId: z.string().uuid('customerId must be a valid UUID').optional().nullable(),
  notes: z.string().max(2000).optional().nullable(),
})

/** Input for updating an existing quote (draft fields only) */
export type UpdateQuoteInput = z.infer<typeof updateQuoteSchema>

// ---------------------------------------------------------------------------
// Create Quote Line Item Input
// ---------------------------------------------------------------------------

const baseLineItemFields = {
  lineType: quoteLineItemTypeSchema,
  description: z.string().min(1, 'description is required').max(500),
  quantity: z.number().int().positive('quantity must be a positive integer'),
  unitPriceNet: z.number().int().nonnegative('unitPriceNet must be a non-negative integer (cents)'),
  vatRateId: z.string().min(1, 'vatRateId is required').max(50),
  discountPercent: z.number().int().min(0).max(10000).nullable().optional(), // basis points, nullable = no discount
}

export const createQuoteLineItemPartSchema = z.object({
  ...baseLineItemFields,
  lineType: z.literal('part'),
  partId: z.string().uuid('partId must be a valid UUID').optional().nullable(),
})

export const createQuoteLineItemLaborSchema = z.object({
  ...baseLineItemFields,
  lineType: z.literal('labor'),
  laborServiceId: z.string().uuid('laborServiceId must be a valid UUID').optional().nullable(),
})

export const createQuoteLineItemBicycleSchema = z.object({
  ...baseLineItemFields,
  lineType: z.literal('bicycle'),
  bicycleId: z.string().uuid('bicycleId must be a valid UUID').optional().nullable(),
  bicycleBrand: z.string().max(100).optional().nullable(),
  bicycleModel: z.string().max(200).optional().nullable(),
  bicycleYear: z.number().int().min(1900).max(new Date().getFullYear() + 1).optional().nullable(),
  bicycleColor: z.string().max(50).optional().nullable(),
  bicycleFrameSize: z.string().max(20).optional().nullable(),
})

/** Discriminated union for creating a quote line item */
export const createQuoteLineItemSchema = z.discriminatedUnion('lineType', [
  createQuoteLineItemPartSchema,
  createQuoteLineItemLaborSchema,
  createQuoteLineItemBicycleSchema,
])

/** Input for creating a new quote line item */
export type CreateQuoteLineItemInput = z.infer<typeof createQuoteLineItemSchema>

// ---------------------------------------------------------------------------
// Update Quote Line Item Input
// ---------------------------------------------------------------------------

const baseUpdateLineItemFields = {
  description: z.string().min(1, 'description is required').max(500).optional(),
  quantity: z.number().int().positive('quantity must be a positive integer').optional(),
  unitPriceNet: z.number().int().nonnegative('unitPriceNet must be a non-negative integer (cents)').optional(),
  vatRateId: z.string().min(1, 'vatRateId is required').max(50).optional(),
  discountPercent: z.number().int().min(0).max(10000).nullable().optional(), // basis points
}

export const updateQuoteLineItemPartSchema = z.object({
  ...baseUpdateLineItemFields,
  lineType: z.literal('part'),
  partId: z.string().uuid('partId must be a valid UUID').optional().nullable(),
})

export const updateQuoteLineItemLaborSchema = z.object({
  ...baseUpdateLineItemFields,
  lineType: z.literal('labor'),
  laborServiceId: z.string().uuid('laborServiceId must be a valid UUID').optional().nullable(),
})

export const updateQuoteLineItemBicycleSchema = z.object({
  ...baseUpdateLineItemFields,
  lineType: z.literal('bicycle'),
  bicycleId: z.string().uuid('bicycleId must be a valid UUID').optional().nullable(),
  bicycleBrand: z.string().max(100).optional().nullable(),
  bicycleModel: z.string().max(200).optional().nullable(),
  bicycleYear: z.number().int().min(1900).max(new Date().getFullYear() + 1).optional().nullable(),
  bicycleColor: z.string().max(50).optional().nullable(),
  bicycleFrameSize: z.string().max(20).optional().nullable(),
})

/** Discriminated union for updating a quote line item */
export const updateQuoteLineItemSchema = z.discriminatedUnion('lineType', [
  updateQuoteLineItemPartSchema,
  updateQuoteLineItemLaborSchema,
  updateQuoteLineItemBicycleSchema,
])

/** Input for updating an existing quote line item */
export type UpdateQuoteLineItemInput = z.infer<typeof updateQuoteLineItemSchema>

import { z } from 'zod'
import { paymentMethodSchema } from './sales.js'

/** Line item for a customer order — supports parts, labor, and bicycles */
export const customerOrderLineItemSchema = z.object({
  lineType: z.enum(['part', 'labor', 'bicycle']),
  partId: z.string().nullable().optional(),
  laborServiceId: z.string().nullable().optional(),
  description: z.string().min(1, 'description is required').max(500),
  quantity: z.number().int().positive('quantity must be a positive integer'),
  unitPriceNet: z.number().int().nonnegative('unitPriceNet must be non-negative'),
  vatRateId: z.string().min(1, 'vatRateId is required'),
  discountPercent: z.number().int().nonnegative().nullable().optional(),
  // Bicycle-specific fields (only used when lineType='bicycle')
  bicycleId: z.string().nullable().optional(),
  bicycleBrand: z.string().nullable().optional(),
  bicycleModel: z.string().nullable().optional(),
  bicycleYear: z.number().int().nullable().optional(),
  bicycleColor: z.string().nullable().optional(),
  bicycleFrameSize: z.string().nullable().optional(),
})

export type CustomerOrderLineItem = z.infer<typeof customerOrderLineItemSchema>

/** Input for creating a customer order with optional deposit */
export const createCustomerOrderInputSchema = z.object({
  customerId: z.string().min(1, 'customerId is required'),
  lineItems: z.array(customerOrderLineItemSchema).min(1, 'At least one line item is required'),
  depositAmount: z.number().int().nonnegative('depositAmount must be non-negative').nullable().optional(),
  paymentMethod: paymentMethodSchema.nullable().optional(),
  expectedDeliveryDate: z.string().datetime().nullable().optional(),
  internalNotes: z.string().max(2000).nullable().optional(),
}).refine(
  (data) => {
    // If depositAmount > 0, paymentMethod must be provided
    if ((data.depositAmount ?? 0) > 0 && !data.paymentMethod) {
      return false
    }
    return true
  },
  { message: 'paymentMethod is required when depositAmount > 0', path: ['paymentMethod'] }
)

export type CreateCustomerOrderInput = z.infer<typeof createCustomerOrderInputSchema>

/** Customer order status */
export const customerOrderStatusSchema = z.enum(['pending', 'ordered', 'ready', 'fulfilled', 'cancelled'])
export type CustomerOrderStatus = z.infer<typeof customerOrderStatusSchema>

/**
 * Explicit TypeScript interfaces for repair-related entities.
 * Mirrors the DB schema but is decoupled from Drizzle inference.
 * Both client and server import these as single source of truth.
 */

// ============================================================================
// Repair Status — lifecycle states
// ============================================================================

export type RepairStatus = 'intake' | 'in_progress' | 'on_hold' | 'verified' | 'ready' | 'completed' | 'cancelled'

/** Valid status transitions from a given source status */
export const VALID_TRANSITIONS: Record<RepairStatus, RepairStatus[]> = {
  intake: ['in_progress'],
  in_progress: ['on_hold', 'verified'],
  on_hold: ['in_progress'],
  verified: ['ready'],
  ready: ['completed'],
  completed: [], // terminal — no transitions allowed (except via cancel)
  cancelled: [], // terminal
}

/** All statuses that can be reached from any state */
export const CANCEL_TARGETS: RepairStatus[] = [
  'intake', 'in_progress', 'on_hold', 'verified', 'ready'
]

// ============================================================================
// Hold Reason — why a repair is paused
// ============================================================================

export type HoldReason = 'waiting_parts' | 'awaiting_customer_approval' | 'other'

// ============================================================================
// Repair Header
// ============================================================================

/** A repair record representing a bicycle service job */
export interface Repair {
  /** Unique identifier (client-generated UUID) */
  id: string
  /** Bicycle being serviced */
  bicycleId: string
  /** Assigned technician (NULL = unassigned, deferred dispatch) */
  assignedTo: string | null
  /** Current status in the lifecycle */
  status: RepairStatus
  /** Notes visible to customer */
  customerNotes: string | null
  /** Internal technician observations */
  internalNotes: string | null
  /** Reason for being on hold (requires note when set) */
  holdReason: HoldReason | null
  /** Explanation for the hold reason */
  holdReasonNote: string | null
  /** Scheduled start/completion date */
  plannedDate: number | null // epoch ms timestamp
  /** Customer collection date */
  pickupDate: number | null // epoch ms timestamp
  /** When payment was completed */
  completedAt: number | null // epoch ms timestamp
  /** Creation timestamp */
  createdAt: number // epoch ms timestamp
}

// ============================================================================
// Repair Line Item — parts used and labor logged
// ============================================================================

/** Type of line item in a repair */
export type RepairLineItemType = 'part' | 'labor'

/** A line item on a repair (parts or labor) */
export interface RepairLineItem {
  /** Unique identifier */
  id: string
  /** Parent repair ID */
  repairId: string
  /** Type of line item */
  lineType: RepairLineItemType
  /** Reference to part catalog (NULL for labor items) */
  partId: string | null
  /** Reference to labor service catalog (NULL for parts) */
  laborServiceId: string | null
  /** Human-readable description */
  description: string
  /** Quantity (default 1) */
  quantity: number
  /** Unit price ex-tax in cents */
  unitPriceNet: number
  /** VAT rate reference ID */
  vatRateId: string
  /** Discount basis points (nullable = no discount) */
  discountPercent: number | null
  /** Net total after discount */
  lineTotalNet: number
  /** VAT amount */
  lineTotalVat: number
  /** Gross total incl. VAT */
  lineTotalGross: number
  /** Billing minutes worked (for hourly labor) */
  minutesWorked: number | null
  /** Worker's rate at time of logging (hourly services) */
  hourlyRateSnapshot: number | null
  /** Creation timestamp */
  createdAt: number // epoch ms timestamp
}

// ============================================================================
// Work Log — timer session per repair
// ============================================================================

/** A manual work timer session for a repair */
export interface WorkLog {
  /** Unique identifier */
  id: string
  /** Parent repair ID */
  repairId: string
  /** Technician who worked (user ID) */
  userId: string
  /** When the timer started */
  startedAt: number // epoch ms timestamp
  /** When the timer stopped (NULL if still running) */
  endedAt: number | null // epoch ms timestamp
  /** Duration in milliseconds (only when endedAt is set) */
  durationMs?: number
}

// ============================================================================
// Status History — audit trail for transitions
// ============================================================================

/** A single status transition record */
export interface RepairStatusHistory {
  /** Unique identifier */
  id: string
  /** Parent repair ID */
  repairId: string
  /** The status this record represents */
  status: RepairStatus
  /** When the transition occurred */
  transitionedAt: number // epoch ms timestamp
}

// ============================================================================
// Intake Input — combined customer + bicycle + notes for new repairs
// ============================================================================

/** Customer lookup result during intake (compact shape) */
export interface IntakeCustomer {
  id: string
  type: 'private' | 'company'
  firstName: string | null
  lastName: string | null
  companyName: string | null
  phone: string | null
  email: string | null
}

/** Bicycle option during intake (compact shape) */
export interface IntakeBicycle {
  id: string
  brand: string
  model: string
  color: string | null
  year: number | null
}

/** Customer selection mode for intake */
export type CustomerMode = 'existing' | 'new'

/** Bicycle selection mode for intake */
export type BicycleMode = 'select_existing' | 'create_new'

/** Input shape for the repair intake form */
export interface RepairIntakeInput {
  /** Whether selecting existing or creating new customer */
  customerMode: CustomerMode
  /** Existing customer ID (when customerMode='existing') */
  existingCustomerId?: string
  /** New customer data (when customerMode='new') */
  newCustomer?: {
    firstName?: string
    lastName?: string
    companyName?: string
    phone: string
    email: string
  }
  /** Whether selecting existing or creating new bicycle */
  bicycleMode: BicycleMode
  /** Existing bicycle ID (when bicycleMode='select_existing') */
  existingBicycleId?: string
  /** New bicycle data (when bicycleMode='create_new') */
  newBicycle?: {
    brand: string
    model: string
    color: string
  }
  /** Customer-facing notes captured at intake */
  customerNotes: string
  /** Scheduled start/completion date (optional, epoch ms) */
  plannedDate?: number | null
  /** Customer collection/pickup date (optional, epoch ms) */
  pickupDate?: number | null
}

// ============================================================================
// Repair Detail — enriched shape with line items and work logs
// ============================================================================

/** A repair detail response including all related data */
export interface RepairDetail {
  /** The repair header */
  repair: Repair
  /** Customer associated with the bicycle */
  customer?: {
    id: string
    firstName: string | null
    lastName: string | null
    companyName: string | null
    phone: string | null
    email: string | null
  }
  /** Bicycle being serviced */
  bicycle: {
    id: string
    brand: string
    model: string
    color: string | null
    year: number | null
  }
  /** Line items (parts and labor) for this repair */
  lineItems: RepairLineItem[]
  /** Work log timer sessions for this repair */
  workLogs: WorkLog[]
}

// ============================================================================
// Labor Service — predefined service catalog entry
// ============================================================================

/** A labor service from the predefined catalog */
export interface LaborService {
  id: string
  name: string
  description: string | null
  billingType: 'hourly' | 'fixed'
  defaultRate: number // cents/hour for hourly, fixed amount for fixed-rate
  isActive: boolean
}

// ============================================================================
// Line Item Input — creating/updating repair line items
// ============================================================================

/** Input for creating a part-based line item */
export interface CreatePartLineItemInput {
  /** Type of line item (always 'part' for this variant) */
  lineType: 'part'
  /** Part ID from the catalog */
  partId: string
  /** Human-readable description (snapshotted at creation) */
  description: string
  /** Quantity of parts used */
  quantity: number
  /** Unit price ex-tax in cents */
  unitPriceNet: number
  /** VAT rate reference ID */
  vatRateId: string
  /** Discount basis points (nullable = no discount) */
  discountPercent?: number | null
}

/** Input for creating a labor-based line item */
export interface CreateLaborLineItemInput {
  /** Type of line item (always 'labor' for this variant) */
  lineType: 'labor'
  /** Labor service ID from the catalog */
  laborServiceId: string
  /** Human-readable description (snapshotted at creation) */
  description: string
  /** Quantity (usually 1 for labor) */
  quantity: number
  /** Unit price ex-tax in cents */
  unitPriceNet: number
  /** VAT rate reference ID */
  vatRateId: string
  /** Discount basis points (nullable = no discount) */
  discountPercent?: number | null
  /** Minutes worked for billing purposes */
  minutesWorked?: number | null
  /** Worker's hourly rate snapshot at time of logging */
  hourlyRateSnapshot?: number | null
}

/** Union type for creating any line item on a repair */
export type CreateRepairLineItemInput = CreatePartLineItemInput | CreateLaborLineItemInput

/** Input for updating an existing repair line item */
export interface UpdateRepairLineItemInput {
  /** Quantity (for parts) */
  quantity?: number
  /** Unit price ex-tax in cents */
  unitPriceNet?: number
  /** Discount basis points */
  discountPercent?: number | null
  /** Minutes worked (for labor items) */
  minutesWorked?: number | null
  /** Hourly rate snapshot (for hourly labor items) */
  hourlyRateSnapshot?: number | null
}

// ============================================================================
// Worker Assignment — reassigning a repair to a different technician
// ============================================================================

/** Input for assigning or changing the assigned worker on a repair */
export interface AssignWorkerInput {
  /** Worker ID to assign (nullable to unassign) */
  assignedTo: string | null
}

// ============================================================================
// Payment Completion — atomic transaction at repair completion
// ============================================================================

/** A single payment method entry for split payments */
export interface RepairPaymentMethod {
  /** Payment method */
  method: 'cash' | 'card'
  /** Amount in cents to charge via this method */
  amount: number
}

/** Input for completing a repair with payment data (single or split) */
export interface CompleteRepairInput {
  /** Array of payment methods — single entry for single-payment, multiple for split */
  payments: RepairPaymentMethod[]
}

/** Result returned after successful repair completion */
export interface CompleteRepairResult {
  /** The updated repair record with completedAt set */
  repair: {
    id: string
    bicycleId: string
    assignedTo: string | null
    status: RepairStatus
    customerNotes: string | null
    internalNotes: string | null
    holdReason: HoldReason | null
    holdReasonNote: string | null
    plannedDate: number | null
    pickupDate: number | null
    completedAt: number | null
    createdAt: number
  }
  /** The linked sale record created for revenue attribution */
  sale: {
    id: string
    saleNumber: string
    customerId: string | null
    sourceType: 'direct_sale' | 'repair' | 'customer_order' | 'backorder'
    sourceId: string | null
    status: 'completed' | 'voided'
    subtotalNet: number
    vatTotal: number
    totalGross: number
  }
  /** All payments created for this completion */
  payments: Array<{
    id: string
    method: 'cash' | 'card' | 'bank_transfer'
    amount: number
  }>
  /** Stock movements created for parts used */
  stockMovements: Array<{
    id: string
    partId: string
    quantityDelta: number
    reason: string
    referenceType: string
    referenceId: string
  }>
}

